import { AdminApp, type AdminBranding } from "@emdash-cms/admin";
import type { Messages } from "@lingui/core";
import { lazy, Suspense } from "react";
// @ts-ignore - virtual module generated by integration
import { loadPluginAdmins } from "virtual:emdash/admin-loader";
// @ts-ignore - virtual module generated by integration
import { authProviders } from "virtual:emdash/auth-providers";

interface AdminWrapperProps {
	locale: string;
	messages: Messages;
	/** Configured admin white-label branding (logo, site name), read server-side from `admin.astro`. */
	adminBranding?: AdminBranding;
}

const PluginAdminApp = lazy(async () => {
	const { pluginAdmins } = await loadPluginAdmins();
	return {
		default: ({ locale, messages, adminBranding }: AdminWrapperProps) => (
			<AdminApp
				pluginAdmins={pluginAdmins}
				authProviders={authProviders}
				adminBranding={adminBranding}
				locale={locale}
				messages={messages}
			/>
		),
	};
});

export default function AdminWrapper(props: AdminWrapperProps) {
	return (
		<Suspense fallback={null}>
			<PluginAdminApp {...props} />
		</Suspense>
	);
}
